<script setup>
import {onMounted,ref} from 'vue';import {useAdminAuthStore} from '../stores/adminAuth.js';import {fetchPlatformStores} from '../services/adminSession.js'
const auth=useAdminAuthStore(),result=ref({items:[],page:1,pageSize:25,total:0}),error=ref('')
async function load(page=1){try{result.value=await fetchPlatformStores({apiUrl:import.meta.env.VITE_API_URL||'',accessToken:auth.session.access_token,page,pageSize:result.value.pageSize})}catch{error.value='Mağaza listesi yüklenemedi.'}}
function date(v){return v?new Intl.DateTimeFormat('tr-TR',{dateStyle:'medium'}).format(new Date(v)):'—'}onMounted(()=>load())
</script>
<template><main class="dashboard"><header><div><div class="eyebrow">PLATFORM OPERASYONLARI</div><h1>Mağazalar</h1></div><RouterLink class="button-link secondary" to="/dashboard">Genel duruma dön</RouterLink></header><p v-if="error" class="notice">{{error}}</p><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Mağaza</th><th>Workspace</th><th>Storefront</th><th>Kurulum</th><th>Abonelik</th><th>Dönem sonu</th></tr></thead><tbody><tr v-for="store in result.items" :key="store.id"><td><RouterLink :to="`/stores/${store.id}`"><strong>{{store.name}}</strong></RouterLink><small>{{store.myshopifyDomain}} · {{store.status}}</small></td><td>{{store.workspace.name}}</td><td>{{store.storefront?.status||'Yok'}}</td><td>{{store.onboarding.completed}} / {{store.onboarding.total}}</td><td>{{store.subscription?.status||'Yok'}}<small>{{store.subscription?.planKey}}</small></td><td>{{date(store.subscription?.currentPeriodEnd)}}</td></tr></tbody></table></div></section></main></template>
